(()=>{const zh=document.documentElement.lang.startsWith('zh'),keys=['concentration','analyteFactor','standardFactor'],defaults={concentration:8,analyteFactor:.55,standardFactor:.55};const get=k=>document.getElementById('C03-'+k);let state={};function update(){let c=+get('concentration').value,f=+get('analyteFactor').value,g=+get('standardFactor').value;keys.forEach(k=>get(k+'-value').textContent=(+get(k).value).toFixed(2));state={concentration:c,analyteFactor:f,standardFactor:g,external_concentration:c*f,ratio_concentration:c*f/g,analyte_response:1000*c*f,standard_response:12500*g};get('result').textContent=(zh?'真实浓度：':'True concentration: ')+c.toFixed(2)+' ng/mL; '+(zh?'外标反算：':'external estimate: ')+state.external_concentration.toFixed(2)+' ng/mL; '+(zh?'内标比值反算：':'ratio estimate: ')+state.ratio_concentration.toFixed(2)+' ng/mL';const vals=[state.analyte_response,state.standard_response],cols=['#167d9a','#d35f47'];let out='<rect width="760" height="350" fill="#fcfbf7"/><path d="M80 35V280H720" stroke="#61758a" fill="none"/>';for(let j=0;j<=4;j++){const v=j*5000,y=280-v/20000*230;out+='<text x="70" y="'+(y+4)+'" text-anchor="end" font-size="12">'+v+'</text>';}vals.forEach((v,i)=>{let x=190+i*300,y=280-v/20000*230;out+='<rect x="'+x+'" y="'+y+'" width="100" height="'+(280-y)+'" fill="'+cols[i]+'"/><text x="'+(x+50)+'" y="'+(y-9)+'" text-anchor="middle" font-size="15">'+v.toFixed(0)+'</text><text x="'+(x+50)+'" y="310" text-anchor="middle" font-size="14">'+(i?(zh?'内标':'Internal standard'):(zh?'目标物':'Analyte'))+'</text>';});out+='<text x="90" y="22" font-size="13">'+(zh?'背景扣除后的响应 / 任意单位':'Background-corrected response / arbitrary units')+'</text>';get('plot').innerHTML=out;}function set(p){keys.forEach(k=>{if(p[k]!==undefined){const e=get(k);e.value=Math.max(+e.min,Math.min(+e.max,+p[k]));}});update();}keys.forEach(k=>get(k).addEventListener('input',update));get('reset').addEventListener('click',()=>set(defaults));window.CourseLab={set,state:()=>({...state}),reset:()=>set(defaults)};update();})();
